"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["44213"],{13975(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.endereco_referencia.origem_obrigatoria","status":422,"titulo":"Origem do endere\xe7o \xe9 obrigat\xf3ria"},"descricao":{"codigo":"uniplus.endereco_referencia.origem_obrigatoria","requisitos":[],"oQueAconteceu":["A `origem` do endere\xe7o estruturado est\xe1 ausente, nula, vazia ou s\xf3 com espa\xe7os. O campo registra de onde veio a resolu\xe7\xe3o do endere\xe7o (o servi\xe7o de localidades que respondeu). A mensagem \xe9 `Origem da resolu\xe7\xe3o do endere\xe7o \xe9 obrigat\xf3ria.`","O endere\xe7o estruturado \xe9 opcional no cadastro do campus, do local de oferta e da institui\xe7\xe3o (a sede): sem o objeto `endereco` no corpo da requisi\xe7\xe3o, nenhuma confer\xeancia dele ocorre. Com o objeto, a API confere os campos um de cada vez e para na primeira recusa, nesta ordem: CEP informado, CEP com 8 d\xedgitos, cidade do endere\xe7o (as recusas da fam\xedlia [refer\xeancia de cidade](/erros/uniplus.cidade_referencia.codigo_ibge_obrigatorio)), tamanho dos textos (logradouro, n\xfamero, complemento, bairro e distrito), latitude, longitude, n\xedvel de resolu\xe7\xe3o informado, n\xedvel de resolu\xe7\xe3o dentro do vocabul\xe1rio, origem informada e tamanho da origem.","A recusa vem na lista `errors` da resposta, com `field` igual a `endereco`, ao lado das recusas dos outros campos do mesmo cadastro, que s\xe3o conferidos no mesmo pedido. O `code` da resposta \xe9 o da primeira recusa da lista, e as recusas dos campos do pr\xf3prio cadastro (como `sigla`, `nome` e a cidade) v\xeam antes da do endere\xe7o. Nada \xe9 gravado. Na atualiza\xe7\xe3o, estas confer\xeancias v\xeam antes da busca do registro: um `{id}` que n\xe3o existe, enviado com endere\xe7o recusado, recebe esta recusa, e s\xf3 o corpo aceito chega \xe0 resposta de [campus n\xe3o encontrado](/erros/uniplus.configuracao.campus.nao_encontrado), de [local de oferta n\xe3o encontrado](/erros/uniplus.configuracao.local_oferta.nao_encontrado) ou de [institui\xe7\xe3o n\xe3o encontrada](/erros/uniplus.organizacao.instituicao.nao_encontrada)."],"comoResolver":["Informe a `origem` da resolu\xe7\xe3o, com no m\xe1ximo 50 caracteres."],"ondeAparece":["Cria\xe7\xe3o de um campus","Atualiza\xe7\xe3o de um campus","Cria\xe7\xe3o de um local de oferta","Atualiza\xe7\xe3o de um local de oferta","Cria\xe7\xe3o da institui\xe7\xe3o","Atualiza\xe7\xe3o da institui\xe7\xe3o"]},"modulo":{"id":"transversais","nome":"Erros transversais","assunto":"Endereco referencia"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"137e6bdd986deaebbd7281a2e43c40e18a247a98"}}')}}]);